<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Snippet\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Document\Snippet\Domain\ValueObject\SnippetEnabledVO;

trait SnippetEnabledAccessor
{
    private ?SnippetEnabledVO $_enabled = null;
    public function isEnabled(): ?bool
    {
        return $this->_enabled?->value();
    }
    public function enabled(): ?SnippetEnabledVO
    {
        return $this->_enabled;
    }
    public function isEnabledChanged(?self $original = null): bool
    {
        return null !== $this->_enabled && !$this->_enabled->equals($original?->_enabled);
    }
    public function withEnabled(SnippetEnabledVO|bool|null $enabled): self
    {
        $copy = clone $this;
        $copy->_enabled = SnippetEnabledVO::from($enabled);
        return $copy;
    }
}
